const InventoryManagement = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [showSortModal, setShowSortModal] = useState(false);
  const [sortType, setSortType] = useState('a-z');
  const [viewType, setViewType] = useState('products'); // products or categories

  const [showFormModal, setShowFormModal] = useState(false);
  const [formType, setFormType] = useState('add');
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);
  const [showStatusDropdown, setShowStatusDropdown] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    sku: '',
    barcode: '',
    category: "Men's Wear",
    status: 'Active',
    price: '',
    tax: '',
    qty: '',
    discountEnabled: true,
    discountTitle: '',
    discountAmount: '',
    image: null,
    description: '',
  });

  const [showCatFormModal, setShowCatFormModal] = useState(false);
  const [catFormData, setCatFormData] = useState({
    name: '',
    status: 'Active',
    products: '',
    vendor: '',
    image: null,
  });
  const [showCatStatusDropdown, setShowCatStatusDropdown] = useState(false);

  const sortedData = useMemo(() => {
    let data = viewType === 'products' ? [...dummyData] : [...dummyCategories];
    if (sortType === 'a-z' || sortType === 'name') {
      data.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortType === 'z-a') {
      data.sort((a, b) => b.name.localeCompare(a.name));
    }

    if (searchQuery.trim() !== '') {
      data = data.filter(item => item.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }

    return data;
  }, [sortType, searchQuery, viewType]);

  const handleSortSelect = type => {
    setSortType(type);
    setShowSortModal(false);
  };

  const handleCreateNew = () => {
    setFormType('add');
    if (viewType === 'products') {
      setFormData({
        name: '',
        sku: '',
        barcode: '',
        category: "Men's Wear",
        status: 'Active',
        price: '',
        tax: '',
        qty: '',
        discountEnabled: true,
        discountTitle: '',
        discountAmount: '',
        image: null,
        description: '',
      });
      setShowFormModal(true);
    } else {
      setCatFormData({
        name: '',
        status: 'Active',
        products: '',
        vendor: '',
        image: null,
      });
      setShowCatFormModal(true);
    }
  };

  const handleEdit = item => {
    setFormType('edit');
    if (viewType === 'products') {
      setFormData({
        name: item.name || '',
        sku: item.sku || '',
        barcode: item.barcode || '',
        category: item.category || "Men's Wear",
        status: item.status || 'Active',
        price: item.price || '',
        tax: '',
        qty: item.qty || '',
        discountEnabled: true,
        discountTitle: item.discount || '',
        discountAmount: '',
        image: null,
        description: '',
      });
      setShowFormModal(true);
    } else {
      setCatFormData({
        name: item.name || '',
        status: item.status || 'Active',
        products: item.products || '',
        vendor: item.vendor || '',
        image: item.image || null,
      });
      setShowCatFormModal(true);
    }
  };

  const handleDelete = item => {
    setSelectedProduct(item);
    setShowDeleteModal(true);
  };

  const confirmDelete = () => {
    setShowDeleteModal(false);
    setTimeout(() => {
      setShowSuccessModal(true);
    }, 500);
  };

  const handleImageUpload = () => {
    launchImageLibrary({ mediaType: 'photo', quality: 0.8 }, response => {
      if (response.didCancel || response.errorMessage) {
        return;
      }
      if (response.assets && response.assets.length > 0) {
        if (showCatFormModal) {
          setCatFormData({ ...catFormData, image: response.assets[0].uri });
        } else {
          setFormData({ ...formData, image: response.assets[0].uri });
        }
      }
    });
  };

  return (
    <View style={styles.root}>
      {/* Header Row */}
      <View style={styles.headerRow}>
        <View style={styles.headerTitleGroup}>
          <Text style={[styles.headerTitle, H1]}>Inventory Management</Text>
