    if (isNewOrder) {
      setCart([]);
      setTipAmount(null);
      setDiscountAmount(0);
      setDiscountCode('');
      setBuyerInfo(null);
    } else {
      setCart([
        { id: 'c1', name: 'Sodavand (25cl)', price: 35.0, qty: 2, note: '' },
        { id: 'c2', name: 'Sodavand (25cl)', price: 35.0, qty: 2, note: '' },
        { id: 'c3', name: 'Sodavand (25cl)', price: 35.0, qty: 2, note: '' },
      ]);
      setTipAmount(null);
      setDiscountAmount(0);
      setDiscountCode('');
      setBuyerInfo(null);
    }
  }, [isNewOrder, tableNumber]);

