import React, { useState, useRef, useEffect, useMemo } from 'react';
import {
  View,
  Text,
  StatusBar,
  TouchableOpacity,
  FlatList,
  Image,
  Modal,
  TouchableWithoutFeedback,
  ScrollView,
} from 'react-native';
import { useNavigation, useRoute } from '@react-navigation/native';
import { Colors } from '../../utils/Colors';
import { S, VS, MS } from '../../utils/Responsive';
import { Subtitle2, Body3, H4, Subtitle1, Overline } from '../../utils/fonts';
import { IconSize12, IconSize16, IconSize20, IconSize40 } from '../../utils/IconSizes';
import {
  LeftArrowIcon,
  RightArrowIcon,
  ArrowDownIcon,
  MenuIcon,
  ImageFrameIcon,
  DeleteIcon,
  TickIcon,
  RefreshICon,
  DiscountIcon,
  DollarIcon,
  BuyersIcon,
  CancelOrderIcon,
} from '../../assets/Images';
import styles from './TableSelectionScreenStyles';
import TipModal from '../../components/TipModal';
import BuyerInfoModal from '../../components/BuyerInfoModal';
import QuickSaleModal from '../../components/QuickSaleModal';
import ProcessOrderModal from '../../components/ProcessOrderModal';
import CartNoteModal from '../../components/CartNoteModal';
import DiscountModal from '../../components/DiscountModal';
import PaymentMethodModal from '../../components/PaymentMethodModal';
import InvoiceModal from '../../components/InvoiceModal';
import TransactionProcessModal from '../../components/TransactionProcessModal';
import ConfirmationModal from '../../components/ConfirmationModal';
import SuccessModal from '../../components/SuccessModal';
import TapCardModal from '../../components/TapCardModal';
import NfcManager, { NfcTech } from 'react-native-nfc-manager';

const categories = [
  { name: 'Beverages', icon: ImageFrameIcon },
  { name: 'Appetizer', icon: ImageFrameIcon },
  { name: 'Drinks', icon: ImageFrameIcon },
  { name: 'Chicken', icon: ImageFrameIcon },
  { name: 'Whiskey', icon: ImageFrameIcon },
  { name: 'Wine', icon: ImageFrameIcon },
  { name: 'Beef', icon: ImageFrameIcon },
];

const dummyProducts = [
  { id: '1', name: 'Sodavand (25cl)', price: 16.23 },
  { id: '2', name: 'Sodavand (25cl)', price: 16.23 },
  { id: '3', name: 'Sodavand (25cl)', price: 16.23 },
  { id: '4', name: 'Sodavand (25cl)', price: 16.23 },
  { id: '5', name: 'Sodavand (25cl)', price: 16.23 },
];

const TableSelectionScreen = () => {
  const navigation = useNavigation();
  const route = useRoute();
  const [activeTab, setActiveTab] = useState('Dine in');
  const [selectedArea, setSelectedArea] = useState('Area: 1 (Ground Floor)');
  const [isAreaDropdownVisible, setIsAreaDropdownVisible] = useState(false);
  const [dropdownPosition, setDropdownPosition] = useState({ top: 0, left: 0, width: 0 });
  const areaSelectorRef = useRef(null);

  const [selectedCategory, setSelectedCategory] = useState('Beverages');
  const [cart, setCart] = useState([]);
  const categoryScrollRef = useRef(null);
  const scrollOffset = useRef(0);

  const [tipAmount, setTipAmount] = useState(null);
  const [showTipModal, setShowTipModal] = useState(false);
  const [buyerInfo, setBuyerInfo] = useState(null);
  const [showBuyerModal, setShowBuyerModal] = useState(false);
  const [showQuickSaleModal, setShowQuickSaleModal] = useState(false);
  const [showDiscountModal, setShowDiscountModal] = useState(false);
  const [discountCode, setDiscountCode] = useState('');
  const [discountAmount, setDiscountAmount] = useState(0);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [showInvoiceModal, setShowInvoiceModal] = useState(false);
  const [showTransactionModal, setShowTransactionModal] = useState(false);
  const [selectedCartItem, setSelectedCartItem] = useState(null);
  const [showNoteModal, setShowNoteModal] = useState(false);
  const [showProcessModal, setShowProcessModal] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [showTapCardModal, setShowTapCardModal] = useState(false);

  const areas = ['Area: 1 (Ground Floor)', 'Area: 2 (1st Floor)', 'Area: 3 ( 2nd Floor )'];

  const [processingTables, setProcessingTables] = useState([1, 3, 5, 15, 17, 19]);

  useEffect(() => {
    if (route.params?.newlyProcessedTable) {
      setProcessingTables(prev => {
        if (!prev.includes(route.params.newlyProcessedTable)) {
          return [...prev, route.params.newlyProcessedTable];
        }
        return prev;
      });
      navigation.setParams({ newlyProcessedTable: undefined });
    }
  }, [route.params?.newlyProcessedTable, navigation]);

  const tables = useMemo(() => {
    return Array.from({ length: 24 }, (_, i) => {
      const tableNum = i + 1;
      const isProcessing = processingTables.includes(tableNum);
      const isModified = tableNum === 1;
      let seats = 4;
      if ([2, 8, 14, 20].includes(tableNum)) {
        seats = 6;
      }
      if ([3, 9, 15, 21].includes(tableNum)) {
        seats = 8;
      }
      if ([4, 10, 16, 22].includes(tableNum)) {
        seats = 10;
      }
      if ([5, 11, 17, 23].includes(tableNum)) {
        seats = 12;
      }
      if ([6, 12, 18, 24].includes(tableNum)) {
        seats = 14;
      }

      return {
        id: tableNum.toString(),
        number: tableNum,
        seats,
        status: isProcessing ? 'Processing' : 'Available',
        isModified,
      };
    });
  }, [processingTables]);

  const toggleDropdown = () => {
    if (areaSelectorRef.current) {
      areaSelectorRef.current.measure((fx, fy, width, height, px, py) => {
        setDropdownPosition({
          top: py + height,
          left: px,
          width,
        });
        setIsAreaDropdownVisible(true);
      });
    }
  };

  const addToCart = product => {
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item =>
          item.productId === product.id ? { ...item, qty: item.qty + 1 } : item,
        );
      }
      return [
        ...prev,
        {
          id: `c_${Date.now()}_${product.id}`,
          productId: product.id,
          name: product.name,
          price: product.price,
          qty: 1,
          note: '',
        },
      ];
    });
  };

  const updateQty = (id, delta) => {
    setCart(prev =>
      prev.map(item => (item.id === id ? { ...item, qty: Math.max(1, item.qty + delta) } : item)),
    );
  };

  const removeItem = id => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const subtotal = cart.reduce((sum, item) => sum + item.price * item.qty, 0);
  const total = (subtotal - discountAmount + (parseFloat(tipAmount) || 0)).toFixed(2);

  const hasQuickSale = cart.some(item => item.productId?.toString().startsWith('quick_'));

  // Modals Handlers
  const handleOpenTipModal = () => setShowTipModal(true);
  const handleAddTip = amount => {
    setTipAmount(amount);
    setShowTipModal(false);
  };
  const handleSaveTip = amount => {
    setTipAmount(amount);
    setShowTipModal(false);
  };
  const handleDeleteTip = () => {
    setTipAmount(null);
    setShowTipModal(false);
  };

  const handleOpenBuyerModal = () => setShowBuyerModal(true);
  const handleAddBuyerInfo = info => {
    setBuyerInfo(info);
    setShowBuyerModal(false);
  };
  const handleSaveBuyerInfo = info => {
    setBuyerInfo(info);
    setShowBuyerModal(false);
  };
  const handleDeleteBuyerInfo = () => {
    setBuyerInfo(null);
    setShowBuyerModal(false);
  };

  const handleQuickSale = ({ name, price }) => {
    const quickItem = {
      id: `quick_${Date.now()}`,
      name,
      price,
      category: 'Quick Sale',
    };
    addToCart({ id: quickItem.id, name: quickItem.name, price: quickItem.price });
    setShowQuickSaleModal(false);
  };

  const handleSaveNote = noteText => {
    setCart(prev =>
      prev.map(item => (item.id === selectedCartItem.id ? { ...item, note: noteText } : item)),
    );
    setShowNoteModal(false);
  };

  const handleSaveDiscount = code => {
    setDiscountCode(code);
    if (code.length > 0) {
      setDiscountAmount(10); // Dummy logic
    } else {
      setDiscountAmount(0);
    }
  };

  const handleDeleteDiscount = () => {
    setDiscountCode('');
    setDiscountAmount(0);
  };

  const handleCloseInvoice = () => {
    setShowInvoiceModal(false);
    setCart([]);
    setTipAmount(null);
    setBuyerInfo(null);
    setDiscountCode('');
    setDiscountAmount(0);
  };

  const confirmCancelOrder = () => {
    setCart([]);
    setTipAmount(null);
    setBuyerInfo(null);
    setDiscountCode('');
    setDiscountAmount(0);
    setShowCancelModal(false);
  };

  useEffect(() => {
    let timer;
    if (showSuccessModal) {
      timer = setTimeout(() => {
        setShowSuccessModal(false);
        setShowInvoiceModal(true);
      }, 2000);
    }
    return () => clearTimeout(timer);
  }, [showSuccessModal]);

  useEffect(() => {
    let timer;
    if (showTransactionModal) {
      timer = setTimeout(() => {
        setShowTransactionModal(false);
        setShowSuccessModal(true);
      }, 2000);
    }
    return () => clearTimeout(timer);
  }, [showTransactionModal]);

  const renderProduct = ({ item }) => (
    <TouchableOpacity
      style={styles.productCard}
      activeOpacity={0.7}
      onPress={() => addToCart(item)}
    >
      <View style={styles.priceTag}>
        <Text style={[styles.priceText, Overline]}>$ {item.price}</Text>
      </View>
      <Image source={ImageFrameIcon} style={styles.productImage} />
      <Text style={[styles.productName, Body3]}>{item.name}</Text>
    </TouchableOpacity>
  );

  const renderTable = ({ item }) => {
    const isProcessing = item.status === 'Processing';

    // Screenshot exact colors:
    // Available Table: Core = #A4B4FF, Chairs = #3E468A
    // Processing Table: Core = #FEE4C1, Chairs = #FEE4C1
    const coreColor = isProcessing ? '#FEE4C1' : '#A4B4FF';
    const chairColor = isProcessing ? '#FEE4C1' : '#3E468A';

    return (
      <TouchableOpacity
        style={styles.tableWrapper}
        activeOpacity={0.7}
        onPress={() => {
          if (isProcessing) {
            navigation.navigate('OrderProcessingScreen', {
              tableNumber: item.number,
              orderType: 'Dine in',
              isNewOrder: false,
            });
          } else {
            navigation.navigate('OrderProcessingScreen', {
              tableNumber: item.number,
              orderType: 'Dine in',
              isNewOrder: true,
            });
          }
        }}
      >
        {/* Top Chair */}
        <View style={[styles.chairTop, { top: '5%', left: '35%', backgroundColor: chairColor }]} />
        {/* Bottom Chair */}
        <View
          style={[styles.chairBottom, { bottom: '5%', left: '35%', backgroundColor: chairColor }]}
        />
        {/* Left Chair */}
        <View style={[styles.chairLeft, { left: '5%', top: '35%', backgroundColor: chairColor }]} />
        {/* Right Chair */}
        <View
          style={[styles.chairRight, { right: '5%', top: '35%', backgroundColor: chairColor }]}
        />

        {/* Table Core (the square part) */}
        <View style={[styles.tableCore, { backgroundColor: coreColor }]}>
          <Text style={styles.tableNameText}>Table {item.number}</Text>
          <Text style={{ ...Overline, color: Colors.grey }}>Seats: {item.seats}</Text>

          {isProcessing && (
            <View style={styles.statusIndicatorContainer}>
              <View style={[styles.statusDot, { backgroundColor: '#C8933A' }]} />
              <Text style={{ ...Overline, color: Colors.grey }}>Processing</Text>
            </View>
          )}
          {item.isModified && (
